const r = $('Calendar range').first().json;
const offers = rowsOf('Calendar offers');
const posts = rowsOf('Calendar posts');
const byDate = {};
posts.forEach((p) => { const d = parseDt(p.publish_at).toISODate(); (byDate[d] = byDate[d] || []).push(p); });
const relevant = offers.filter((o) => o.status !== 'rejected' && (!o.ends_on || o.ends_on >= DateTime.fromISO(r.from).minus({ days: 45 }).toISODate()));
const lines = [`Offers (not rejected):`];
relevant.sort((a, b) => (a.launch_date < b.launch_date ? -1 : 1)).forEach((o) => {
  lines.push(`#${o.Id} [${o.status}] ${o.title} | ${o.product}: ${o.offer} | reason (${o.reason_type}): ${o.reason} | launch ${o.launch_date}, reminder ${o.reminder_date}, ends ${o.ends_on}${o.sales_count != null ? ` | result: ${o.sales_count} sales, ${o.revenue ?? '?'} VND` : ''}`);
  if (o.status !== 'done') lines.push(`   must know: ${(o.must_know || '').replace(/\n/g, ' / ')}`, `   must feel: ${(o.must_feel || '').replace(/\n/g, ' / ')}`);
});
if (!relevant.length) lines.push('(none)');
lines.push('', `Days ${r.from} to ${r.to}:`);
for (let d = DateTime.fromISO(r.from, { zone: TZ }); d.toISODate() <= r.to; d = d.plus({ days: 1 })) {
  const iso = d.toISODate();
  const list = (byDate[iso] || []).filter((p) => !['rejected', 'cancelled'].includes(p.status));
  if (!list.length) { lines.push(`${iso} ${d.toFormat('ccc')}: free`); continue; }
  list.forEach((p) => lines.push(`${iso} ${d.toFormat('ccc')} ${parseDt(p.publish_at).toFormat('HH:mm')}: post #${p.Id} [${p.status}] ${p.kind} -> offer #${p.offer_id} | ${p.hook_type || '-'} | ${p.title} | angle: ${p.angle || '-'} | tests: ${(p.hypothesis || '-').slice(0, 160)} | picture: ${p.images ? `${p.images.split('\n').filter(Boolean).length} received` : p.image_brief ? `wanted, none yet (${p.image_brief.slice(0, 80)})` : 'none'} | brief: ${(p.brief || '').replace(/\n/g, ' ').slice(0, 220)}${p.check_report && ((p.status === 'planned' && p.revisions) || p.status === 'publish_failed') ? ` | ${p.status === 'publish_failed' ? 'not published' : 'last check failed'}: ${p.check_report.replace(/\n/g, ' ').slice(0, 300)}` : ''}`));
}
return [{ json: { result: lines.join('\n') } }];

