const newToken = () => Array.from({ length: 24 }, () => 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random() * 36)]).join('');

const i = $('When called').first().json;
const errors = [];
let o = {};
try { o = typeof i.offer === 'object' ? i.offer : parseJson(i.offer); } catch (e) { errors.push(`offer is not a JSON object: ${e.message}`); }
const s = (v) => (v ?? '').toString().trim();
const list = (v) => (Array.isArray(v) ? v : s(v).split('\n')).map(s).filter(Boolean);
const c = {
  title: s(o.title), product: s(o.product), offer_type: s(o.offer_type), offer: s(o.offer),
  reason_type: s(o.reason_type), reason: s(o.reason), launch_date: s(o.launch_date),
  reminder_date: s(o.reminder_date), ends_on: s(o.ends_on), landing_url: s(o.landing_url),
  must_know: list(o.must_know), must_feel: list(o.must_feel), rationale: s(o.rationale),
};
const TYPES = ['percent_off', 'amount_off', 'free_extra', 'buy_one_get_one', 'bundle'];
const REASONS = ['calendar_date', 'milestone', 'limited_capacity', 'playful'];
for (const k of ['title', 'product', 'offer', 'rationale']) if (!c[k]) errors.push(`${k} is empty`);
if (!TYPES.includes(c.offer_type)) errors.push(`offer_type must be one of ${TYPES.join(', ')} (keep the offer simple)`);
if (!REASONS.includes(c.reason_type)) errors.push(`reason_type must be one of ${REASONS.join(', ')}`);
if (c.reason.length < 15) errors.push('reason must say why the offer exists now: buyers justify with it');
if (c.must_know.length < 3 || c.must_know.length > 5) errors.push('must_know needs 3 to 5 lines');
if (c.must_feel.length < 2 || c.must_feel.length > 3) errors.push('must_feel needs 2 or 3 lines');
if (c.landing_url && !/^https?:\/\//.test(c.landing_url)) errors.push('landing_url must be a full link or empty');
const today = DateTime.now().setZone(TZ).startOf('day');
const launch = parseDate(c.launch_date), reminder = parseDate(c.reminder_date), ends = parseDate(c.ends_on);
if (!launch.isValid || !reminder.isValid || !ends.isValid) errors.push('launch_date, reminder_date and ends_on must be YYYY-MM-DD');
else {
  if (launch < today.plus({ days: 7 })) errors.push('launch_date must be at least 7 days away, so education and stories can set it up');
  const gap = reminder.diff(launch, 'days').days;
  if (gap < 2 || gap > 4) errors.push('reminder_date must be 2 to 4 days after launch_date');
  const tail = ends.diff(reminder, 'days').days;
  if (tail < 0 || tail > 3) errors.push('ends_on must be reminder_date or up to 3 days after it');
  const month = c.launch_date.slice(0, 7);
  const active = rowsOf('Offer list').filter((x) => x.status !== 'rejected');
  const sameMonth = active.filter((x) => x.month === month);
  if (sameMonth.length >= 2) errors.push(`${month} already has two offers (#${sameMonth.map((x) => x.Id).join(', #')}); the strategy allows two a month`);
  for (const x of active) {
    const xl = parseDate(x.launch_date), xr = parseDate(x.reminder_date);
    if (!xl.isValid || !xr.isValid) continue;
    if (!(launch >= xr.plus({ days: 7 }) || xl >= reminder.plus({ days: 7 }))) {
      errors.push(`too close to offer #${x.Id} (launch ${x.launch_date}, reminder ${x.reminder_date}): keep at least 7 days between one offer's reminder and the next launch`);
    }
  }
}
if (errors.length) return [{ json: { ok: false, result: `Offer not saved. Fix and call propose_offer again:\n- ${errors.join('\n- ')}` } }];
return [{ json: { ok: true, offer: { ...c, month: c.launch_date.slice(0, 7), must_know: c.must_know.join('\n'), must_feel: c.must_feel.join('\n'), approval_token: newToken() } } }];

const o = $('Check offer').first().json.offer;
const id = $json.id;
const fmt = (d) => `${d.slice(8, 10)}/${d.slice(5, 7)}`;
const bullets = (t) => t.split('\n').map((l) => `• ${l}`).join('\n');
const button = (label, type, a) => ({
  tag: 'column', width: 'auto',
  elements: [{ tag: 'button', type, text: { tag: 'plain_text', content: label }, behaviors: [{ type: 'callback', value: { a, id, t: o.approval_token } }] }],
});
return [{
  json: {
    card: {
      schema: '2.0',
      header: { title: { tag: 'plain_text', content: `Offer #${id}: ${o.title}`.slice(0, 100) }, template: 'red' },
      body: {
        elements: [
          { tag: 'markdown', content: [
            `**${o.product}**: ${o.offer}`,
            `**Why now** (${o.reason_type}): ${o.reason}`,
            `**Launch** ${fmt(o.launch_date)} · **reminder** ${fmt(o.reminder_date)} · **ends** ${fmt(o.ends_on)}`,
            o.landing_url ? `**Link:** ${o.landing_url}` : '',
            `**They must know first:**\n${bullets(o.must_know)}`,
            `**They must feel first:**\n${bullets(o.must_feel)}`,
            `**My reasoning:** ${o.rationale}`,
          ].filter(Boolean).join('\n') },
          { tag: 'column_set', flex_mode: 'flow', columns: [button('Approve', 'primary', 'offer_approve'), button('Reject', 'danger', 'offer_reject')] },
          { tag: 'markdown', content: 'Reply to this card to discuss or change it.' },
        ],
      },
    },
  },
}];

const id = $('Create offer').first().json.id;
const d = $json;
return [{ json: { result: `Saved offer #${id} as proposed. ${d.delivered ? 'The approval card is in your manager\'s Lark.' : `Card ${d.note}.`} Plan its posts once it is approved.` } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
