};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const parseJson = (s) => {
  const t = String(s || '').replace(/```(?:json)?/gi, '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('no JSON object in the model output');
  return JSON.parse(t.slice(a, b + 1));
};

const SELLING = /(\d+\s?%|giảm giá|khuyến mãi|ưu đãi|mã giảm|voucher|đăng ký ngay|mua ngay|chốt đơn|flash sale)/i;
// Briefs may say what a post avoids ("không nhắc ưu đãi"); only a discount figure or a call to buy counts there.
const SELLING_BRIEF = /(\d+\s?%|mã giảm|voucher|đăng ký ngay|mua ngay|chốt đơn|flash sale)/i;

const i = $('When called').first().json;
const settings = settingsOf('Plan settings');
const win = windowOf(settings.post_window);
const offers = rowsOf('Plan offers');
const taken = new Set(rowsOf('Plan taken').map((p) => parseDt(p.publish_at).toISODate()));
const today = DateTime.now().setZone(TZ).startOf('day');
const HOOKS = ['question', 'contrarian', 'story', 'number', 'how_to', 'mistake', 'confession', 'observation', 'other'];
let entries = [];
try {
  const parsed = typeof i.posts === 'object' ? i.posts : JSON.parse(String(i.posts || '').replace(/```(?:json)?/gi, '').trim());
  entries = Array.isArray(parsed) ? parsed : parsed.posts;
  if (!Array.isArray(entries)) throw new Error('expected an array of posts');
} catch (e) {
  return [{ json: { accepted: [], result: `Nothing planned: posts must be a JSON array (${e.message}).` } }];
}
const s = (v) => (v ?? '').toString().trim();
const accepted = [];
const refused = [];
for (const e of entries) {
  const date = s(e.date);
  const d = parseDate(date);
  const kind = s(e.kind);
  const offer = offers.find((o) => o.Id === Number(e.offer_id));
  const why = [];
  if (!d.isValid) why.push('date must be YYYY-MM-DD');
  else {
    if (d <= today) why.push('date must be tomorrow or later');
    if (d > today.plus({ days: 45 })) why.push('plan at most 45 days ahead');
    if (taken.has(date)) why.push('that day already has a post (one post a day)');
  }
  if (!['education', 'story', 'offer_launch', 'offer_reminder'].includes(kind)) why.push('kind must be education, story, offer_launch or offer_reminder');
  if (!offer) why.push(`offer_id must be an approved offer (${offers.map((o) => `#${o.Id}`).join(', ') || 'none approved yet'})`);
  if (offer && d.isValid) {
    if (kind === 'offer_launch' && date !== offer.launch_date) why.push(`offer_launch for #${offer.Id} goes on its launch_date ${offer.launch_date}`);
    if (kind === 'offer_reminder' && date !== offer.reminder_date) why.push(`offer_reminder for #${offer.Id} goes on its reminder_date ${offer.reminder_date}`);
    if (['education', 'story'].includes(kind)) {
      // Connected: a post leads to the next offer whose reminder has not passed on that day.
      const next = offers.find((o) => o.reminder_date >= date);
      if (!next) why.push('no approved offer comes after this day; propose one first');
      else if (next.Id !== offer.Id) why.push(`on ${date} the next offer is #${next.Id}; the post must lead to it`);
    }
  }
  const time = s(e.time).padStart(5, '0');
  if (!validTime(time)) why.push('time must be HH:MM');
  else if (time < win.from || time > win.to) why.push(`time must be between ${win.from} and ${win.to}`);
  if (!s(e.title)) why.push('title is empty');
  if (s(e.brief).length < 60) why.push('brief too thin to write from');
  if (!HOOKS.includes(s(e.hook_type))) why.push(`hook_type must be one of ${HOOKS.join(', ')}`);
  if (!s(e.angle)) why.push('angle is empty');
  if (s(e.hypothesis).length < 15) why.push('hypothesis is required: what this post tests and what you expect');
  if (['education', 'story'].includes(kind) && SELLING_BRIEF.test(`${s(e.title)} ${s(e.brief)}`)) why.push('education and stories do not sell: no discount, price or call to buy');
  if (why.length) { refused.push(`${date || '?'} ${s(e.title)}: ${why.join('; ')}`); continue; }
  taken.add(date);
  accepted.push({
    title: s(e.title), kind, offer_id: offer.Id, brief: s(e.brief), hook_type: s(e.hook_type),
    angle: s(e.angle), hypothesis: s(e.hypothesis), image_brief: s(e.image_brief), publish_at: `${date}T${time}:00+07:00`,
  });
}
return [{ json: { accepted, refused, result: '' } }];

const c = $('Check plan').first().json;
const created = $('Create posts').isExecuted ? $('Create posts').all().map((i, n) => `#${i.json.id} ${c.accepted[n].publish_at.slice(0, 10)} ${c.accepted[n].kind}: ${c.accepted[n].title}`) : [];
const lines = [];
if (created.length) lines.push(`Planned ${created.length}:`, ...created);
if (c.refused.length) lines.push(`Refused ${c.refused.length} (fix and plan them again):`, ...c.refused);
if (c.result) lines.push(c.result);
return [{ json: { result: lines.join('\n') || 'Nothing to plan.' } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const SELLING = /(\d+\s?%|giảm giá|khuyến mãi|ưu đãi|mã giảm|voucher|đăng ký ngay|mua ngay|chốt đơn|flash sale)/i;
// Briefs may say what a post avoids ("không nhắc ưu đãi"); only a discount figure or a call to buy counts there.
const SELLING_BRIEF = /(\d+\s?%|mã giảm|voucher|đăng ký ngay|mua ngay|chốt đơn|flash sale)/i;

const i = $('When called').first().json;
const p = rowsOf('Update target')[0];
const refuse = (msg) => [{ json: { ok: false, result: `Post not changed: ${msg}` } }];
if (!p) return refuse(`post #${i.post_id} does not exist`);
if (!['planned', 'awaiting_approval', 'approved', 'publish_failed'].includes(p.status)) return refuse(`post #${p.Id} is ${p.status}`);
let ch = {};
try { ch = typeof i.changes === 'object' ? i.changes : JSON.parse(String(i.changes || '{}')); } catch (e) { return refuse('changes must be a JSON object'); }
const s = (v) => (v ?? '').toString().trim();
const next = {
  title: p.title, brief: p.brief, hook_type: p.hook_type, angle: p.angle, hypothesis: p.hypothesis, image_brief: p.image_brief || '',
  publish_at: p.publish_at, status: p.status, approval_token: p.approval_token || '',
};
if (ch.cancel === true || ch.cancel === 'true') {
  next.status = 'cancelled';
  return [{ json: { ok: true, id: p.Id, next, result: `Post #${p.Id} cancelled; its day is free.` } }];
}
const HOOKS = ['question', 'contrarian', 'story', 'number', 'how_to', 'mistake', 'confession', 'observation', 'other'];
for (const k of ['title', 'brief', 'angle', 'hypothesis', 'image_brief']) if (ch[k] !== undefined) next[k] = s(ch[k]);
if (ch.hook_type !== undefined) {
  if (!HOOKS.includes(s(ch.hook_type))) return refuse(`hook_type must be one of ${HOOKS.join(', ')}`);
  next.hook_type = s(ch.hook_type);
}
if (['education', 'story'].includes(p.kind) && SELLING_BRIEF.test(`${next.title} ${next.brief}`)) return refuse('education and stories do not sell');
const current = parseDt(p.publish_at);
let date = current.toISODate();
let time = current.toFormat('HH:mm');
