if (!goals.length) lines.push('(no active goals)');

lines.push('', `Posts in the window (engagement = reactions + 2 x comments + 3 x shares; score = engagement / median of earlier posts${baseline ? `, median ${fmt(baseline)}` : ''}):`);
if (!posts.some(measured)) lines.push('No post metrics yet: they are read every morning for posts published in the last 8 days. Until then judge from approvals and your manager\'s feedback.');
for (const p of win) {
  lines.push(`#${p.Id} ${parseDt(p.publish_at).toFormat('dd/MM ccc HH:mm')} ${p.kind} [${p.status}] ${p.format || (p.image_brief ? 'picture wanted' : 'text')} hook ${p.hook_type || '-'} | ${p.title} | drafts ${p.revisions || 0}${measured(p) ? ` | unique viewers ${p.reach ?? '-'}, clicks ${p.clicks ?? '-'}, reactions ${p.reactions ?? '-'}, comments ${p.comments ?? '-'}, shares ${p.shares ?? '-'}, score ${fmt(score(p))}` : ''} | tested: ${p.hypothesis || '-'}`);
}
if (!win.length) lines.push('(none)');

const groups = (key) => {
  const g = {};
  win.filter(measured).forEach((p) => { const k = typeof key === 'function' ? key(p) : p[key] || '-'; (g[k] = g[k] || []).push(score(p)); });
  return Object.entries(g).map(([k, xs]) => `${k}: ${xs.length} posts, avg score ${fmt(xs.reduce((a, b) => a + b, 0) / xs.length)}`).join('; ');
};
if (win.some(measured)) {
  lines.push('', `By kind: ${groups('kind')}`, `By hook: ${groups('hook_type')}`, `By time slot: ${groups((p) => slotOf(parseDt(p.publish_at)))}`, `By format: ${groups((p) => p.format || 'text')}`, `By weekday: ${groups((p) => parseDt(p.publish_at).toFormat('ccc'))}`);
}

const byType = (t) => events.filter((e) => e.type === t);
const decided = [...byType('approved'), ...byType('rejected')].filter((e) => e.post_id);
const approvedFirst = byType('approved').filter((e) => {
  const p = posts.find((x) => x.Id === e.post_id);
  return p && Number(p.revisions) === 1 && !byType('change_request').some((c) => c.post_id === e.post_id);
});
lines.push('', `Approvals: ${byType('approved').filter((e) => e.post_id).length} posts approved (${approvedFirst.length} on the first draft without change requests), ${byType('rejected').filter((e) => e.post_id).length} rejected, ${byType('change_request').length} change requests, ${byType('check_failed').length} failed checks.`);
const quote = (list, n) => list.slice(-n).map((e) => `- ${parseDt(e.created_at).toFormat('dd/MM')}${e.post_id ? ` post #${e.post_id}` : ''}${e.offer_id ? ` offer #${e.offer_id}` : ''}: ${(e.text || '').replace(/\n+/g, ' ').slice(0, 400)}`);
if (byType('rejected').length) lines.push('Rejections:', ...quote(byType('rejected'), 10));
if (byType('change_request').length) lines.push('Change requests:', ...quote(byType('change_request'), 15));
if (byType('manager_note').length) lines.push('What your manager said:', ...quote(byType('manager_note'), 20));
if (byType('audience_comment').length) lines.push('Audience comments:', ...quote(byType('audience_comment'), 15));
if (byType('lesson_change').length) lines.push('Playbook changes:', ...quote(byType('lesson_change'), 10));

const done = offers.filter((o) => o.ends_on && parseDt(o.ends_on) >= from.minus({ days: 30 }) && o.status !== 'rejected');
if (done.length) {
  lines.push('', 'Offers:');
  done.forEach((o) => lines.push(`#${o.Id} ${o.title} (${o.offer_type}, reason ${o.reason_type}) ${o.launch_date} to ${o.ends_on} [${o.status}]: ${o.sales_count ?? 'no'} sales, ${o.revenue ?? 'no'} revenue reported${o.result_notes ? ` | ${o.result_notes.replace(/\n+/g, ' ').slice(0, 300)}` : ''}`));
}
const counts = {};
unreviewed.forEach((e) => { counts[e.type] = (counts[e.type] || 0) + 1; });
lines.push('', `Signals not reviewed yet: ${Object.entries(counts).map(([k, n]) => `${n} ${k}`).join(', ') || 'none'}.`);
return [{ json: { result: lines.join('\n') } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const i = $('When called').first().json;
const rows = rowsOf('Playbook');
const s = (v) => (v ?? '').toString().trim();
const refuse = (m) => [{ json: { ok: false, result: `Playbook not changed: ${m}` } }];
const action = s(i.action);
const now = DateTime.now().setZone(TZ).toISO({ suppressMilliseconds: true });
const chat = i.mode === 'chat';
const CATS = ['voice', 'hooks', 'formats', 'topics', 'timing', 'offers', 'planning', 'process'];
const CONF = ['low', 'medium', 'high'];
if (action === 'add') {
  const source = s(i.source) === 'manager' ? 'manager' : 'self';
  if (source === 'manager' && !chat) return refuse('manager directives are recorded only while talking with your manager');
  if (!s(i.lesson)) return refuse('lesson is empty');
  if (s(i.lesson).length > 250) return refuse('keep a lesson to one sentence under 250 characters');
  if (!CATS.includes(s(i.category))) return refuse(`category must be one of ${CATS.join(', ')}`);
  if (!s(i.evidence)) return refuse('evidence is required: the data or the manager\'s words behind it');
  if (source === 'self' && !CONF.includes(s(i.confidence))) return refuse(`confidence must be ${CONF.join(', ')}`);
  if (rows.filter((r) => r.status === 'active').length >= 25) return refuse('25 active lessons already: retire or merge one first');
  return [{ json: { ok: true, action, row: { lesson: s(i.lesson), category: s(i.category), evidence: s(i.evidence), confidence: source === 'manager' ? 'high' : s(i.confidence), source, status: 'active', retired_reason: '', created_at: now, updated_at: now } } }];
}
if (action === 'revise' || action === 'retire') {
  const r = rows.find((x) => x.Id === Number(i.lesson_id));
  if (!r) return refuse(`lesson #${i.lesson_id} does not exist`);
  if (r.source === 'manager' && !chat) return refuse(`lesson #${r.Id} is your manager's directive; only they change it`);
  if (r.status !== 'active') return refuse(`lesson #${r.Id} is already retired`);
  if (!s(i.evidence)) return refuse('evidence is required: why it changes');
  const next = { ...r };
  if (action === 'retire') { next.status = 'retired'; next.retired_reason = s(i.evidence); }
  else {
    if (i.lesson !== undefined && s(i.lesson)) next.lesson = s(i.lesson).slice(0, 250);
    if (CATS.includes(s(i.category))) next.category = s(i.category);
    if (CONF.includes(s(i.confidence)) && r.source !== 'manager') next.confidence = s(i.confidence);
    next.evidence = [r.evidence, `${now.slice(0, 10)}: ${s(i.evidence)}`].filter(Boolean).join('\n');
  }
  next.updated_at = now;
  return [{ json: { ok: true, action, id: r.Id, before: r.lesson, row: next } }];
}
return refuse('action must be add, revise or retire');

const c = $('Check lesson').first().json;
const id = c.action === 'add' ? $('Create lesson').first().json.id : c.id;
const text = c.action === 'add' ? `Added #${id} [${c.row.source}, ${c.row.category}, ${c.row.confidence}]: ${c.row.lesson} | evidence: ${c.row.evidence}`
  : c.action === 'retire' ? `Retired #${id}: ${c.row.lesson} | why: ${c.row.retired_reason}`
  : `Revised #${id}: "${c.before}" -> "${c.row.lesson}" | evidence: ${c.row.evidence.split('\n').pop()}`;
return [{ json: { id, text } }];

