const refuse = (m) => [{ json: { ok: false, result: `Goal not saved: ${m}` } }];
if (i.mode !== 'chat') return refuse('goals are set by your manager; save one only while they are telling you');
const METRICS = ['revenue', 'sales', 'followers', 'engagement', 'reach', 'leads', 'other'];
const STATUS = ['active', 'achieved', 'dropped'];
const row = { title: s(i.title), metric: s(i.metric), target: s(i.target) === '' ? null : Number(s(i.target).replace(/[,\s]/g, '')), unit: s(i.unit), due_on: s(i.due_on), status: s(i.status) || 'active', notes: s(i.notes) };
if (!row.title) return refuse('title is empty');
if (!METRICS.includes(row.metric)) return refuse(`metric must be one of ${METRICS.join(', ')}`);
if (row.target !== null && !Number.isFinite(row.target)) return refuse('target must be a number');
