if (!row.due_on) row.due_on = null;
const id = Number(i.goal_id) || 0;
return [{ json: { ok: true, id, row: { ...row, created_at: DateTime.now().setZone(TZ).toISO({ suppressMilliseconds: true }) } } }];

const c = $('Check goal').first().json;
