const i = $('When called').first().json;
const s = (v) => (v ?? '').toString().trim();
const refuse = (m) => [{ json: { ok: false, result: `Not recorded: ${m}` } }];
const type = s(i.type);
if (!['offer_result', 'audience_comment', 'followers'].includes(type)) return refuse('type must be offer_result, audience_comment or followers (your manager\'s messages are recorded automatically)');
const n = (v) => (s(v) === '' ? null : Number(s(v).replace(/[,\s]/g, '')));
const row = { type, text: s(i.text), post_id: Number(i.post_id) || null, offer_id: Number(i.offer_id) || null, value: null };
let offer = null;
if (type === 'offer_result') {
  const o = rowsOf('Record offer')[0];
  if (!o) return refuse('offer_id must be an existing offer');
  const sales = n(i.sales_count), revenue = n(i.revenue);
  if (sales === null && revenue === null) return refuse('give sales_count, revenue or both');
  if ((sales !== null && !Number.isFinite(sales)) || (revenue !== null && !Number.isFinite(revenue))) return refuse('sales_count and revenue must be numbers');
  const stamp = DateTime.now().setZone(TZ).toFormat('yyyy-MM-dd');
  offer = { Id: o.Id, sales_count: sales ?? o.sales_count ?? null, revenue: revenue ?? o.revenue ?? null, result_notes: [o.result_notes, row.text && `${stamp}: ${row.text}`].filter(Boolean).join('\n'), status: 'done' };
  row.value = revenue;
  row.text = `Offer #${o.Id} ${o.title}: ${offer.sales_count ?? '?'} sales, ${offer.revenue ?? '?'} VND. ${row.text}`;
}
if (type === 'followers') {
  row.value = n(i.value ?? i.text);
  if (!Number.isFinite(row.value)) return refuse('followers needs the follower count as value');
}
if (type === 'audience_comment' && !row.text) return refuse('text is empty');
return [{ json: { ok: true, row, offer } }];
